use dioxus::prelude::*;

pub fn App() -> Element {
    let mut profile_name = use_signal(|| "Ada-1".to_string());
    let mut action_count = use_signal(|| 0u32);
    let mut receipt = use_signal(|| String::new());

    rsx! {
        main {
            "data-route": "direct-rsx",
            div {
                id: "profile_toolbar",
                "data-component": "Toolbar",
                role: "toolbar",
                "aria-orientation": "vertical",
                aria_label: "Profile actions",
                style: "display: flex; flex-direction: column; gap: 0.75rem;",

                div {
                    id: "profile_avatar",
                    "data-component": "Avatar",
                    role: "img",
                    aria_label: "Ada Lovelace · variant 1",
                    style: "width: 64px; height: 64px; display: flex; align-items: center; justify-content: center; background: #6b7280; color: white; font-size: 22px;",
                    "AL"
                }

                label {
                    id: "name_label",
                    "data-component": "Label",
                    r#for: "name_input",
                    "Profile name · variant 1"
                }

                input {
                    id: "name_input",
                    "data-component": "Input",
                    r#type: "text",
                    value: "{profile_name}",
                    placeholder: "Enter a name · variant 1",
                    oninput: move |event| profile_name.set(event.value()),
                    style: "outline: 2px solid #2563eb; outline-offset: 2px;"
                }

                button {
                    id: "submit_button",
                    "data-component": "Button",
                    "data-action": "SubmitProfile",
                    "data-target-id": "profile",
                    r#type: "button",
                    onclick: move |_| {
                        action_count.set(action_count() + 1);
                        receipt.set("receipt:SubmitProfile:profile".to_string());
                    },
                    style: "outline: 2px solid #2563eb; outline-offset: 2px;",
                    "Save profile · variant 1"
                }
            }

            div {
                role: "status",
                "aria-live": "polite",
                "data-action-count": "{action_count}",
                "data-receipt": "{receipt}",
                "{receipt}"
            }
        }
    }
}

use dioxus::prelude::*;

pub fn App() -> Element {
    let mut notifications_enabled = use_signal(|| true);
    let mut terms_accepted = use_signal(|| false);
    let mut action_count = use_signal(|| 0u32);
    let mut receipt = use_signal(|| String::new());

    rsx! {
        main {
            id: "preferences_root",
            "data-route": "direct-rsx",

            section {
                id: "preferences_toolbar",
                "data-component": "Toolbar",
                role: "toolbar",
                "aria-label": "Preferences",
                "aria-orientation": "vertical",

                div {
                    id: "notifications_switch",
                    "data-component": "Switch",

                    label {
                        r#for: "notifications_switch_control",
                        "Enable notifications · variant 1"
                    }
                    input {
                        id: "notifications_switch_control",
                        r#type: "checkbox",
                        role: "switch",
                        checked: notifications_enabled(),
                        "aria-checked": notifications_enabled(),
                        onchange: move |event| {
                            notifications_enabled.set(event.checked());
                        }
                    }
                }

                div {
                    id: "terms_checkbox",
                    "data-component": "Checkbox",

                    label {
                        r#for: "terms_checkbox_control",
                        "Accept terms · variant 1"
                    }
                    input {
                        id: "terms_checkbox_control",
                        r#type: "checkbox",
                        checked: terms_accepted(),
                        onchange: move |event| {
                            terms_accepted.set(event.checked());
                        }
                    }
                }

                button {
                    id: "preferences_button",
                    "data-component": "Button",
                    "data-action": "ApplyFilter",
                    "data-target-id": "preferences",
                    r#type: "button",
                    onclick: move |_| {
                        action_count += 1;
                        receipt.set("receipt:ApplyFilter:preferences".to_string());
                    },
                    "Save preferences · variant 1"
                }
            }

            output {
                role: "status",
                "aria-live": "polite",
                "data-action-count": "{action_count()}",
                "data-receipt": "{receipt()}",
                "{receipt()}"
            }
        }
    }
}

